namespace ghidra.framework.main.wizard.project;







using org.apache.commons.lang3;

using docking.wizard;
using docking.wizard;
using ghidra.app.util;
using ghidra.framework.client;
using ghidra.framework.model;
using ghidra.util;
using ghidra.util;

/**
 * Wizard step in the new project wizard selecting or creating a new repository in a Ghidra server.
 */
public class RepositoryStep : WizardStep<ProjectWizardData> {
	private RepositoryPanel panel;
	private RepositoryServerAdapter server;
	private string[] repositoryNames;

	protected RepositoryStep(WizardModel<ProjectWizardData> model) : base(model, "", new HelpLocation(GenericHelpTopics.FRONT_END, "SelectRepository"))
    {
	}

	/* @Override */
	public Component getDefaultFocusComponent() {
		return panel.getDefaultFocusComponent();
	}

	/* @Override */
	public void initialize(ProjectWizardData data) {
		ServerInfo serverInfo = data.getServerInfo();
		setTitle("Specify Repository Name from server: " + serverInfo.getServerName());
		server = data.getServer();
		repositoryNames = getRepositoryNames();
		if (panel == null) {
			bool readOnly = isServerReadOnly();
			panel = new RepositoryPanel(this.notifyStatusChanged, repositoryNames, readOnly);
		}
	}

	private bool isServerReadOnly() {
		try {
			return server.isReadOnly();
		}
		catch (IOException e) {
			return true;
		}
	}

	private string[] getRepositoryNames() {
		try {
			return server.getRepositoryNames();
		}
		catch (IOException e) {
			return new string[0];
		}
	}

	/* @Override */
	public bool isValid() {
		string repositoryName = panel.getRepositoryName();
		if (panel.isCreateRepositorySelected()) {
			if (repositoryName.length() == 0) {
				return false;
			}
			if (StringUtils.isBlank(repositoryName)) {
				setStatusMessage("Enter project repository name");
				return false;
			}

			try {
				NamingUtilities.checkName(repositoryName,
					"Repository name");
			}
			catch (IllegalArgumentException e) {
				setStatusMessage(e.getMessage());
				return false;
			}

			if (List.of(repositoryNames).contains(repositoryName)) {
				setStatusMessage("Repository " + repositoryName + " already exists");
				return false;
			}
		}
		else if (repositoryName == null) {
			setStatusMessage("Please select a repository");
			return false;
		}
		return true;
	}

	/* @Override */
	public void populateData(ProjectWizardData data) {
		data.setRepositoryName(panel.getRepositoryName());
		data.setIsNewRepository(panel.isCreateRepositorySelected());

	}

	/* @Override */
	public JComponent getComponent() {
		return panel;
	}

	/* @Override */
	public bool apply(ProjectWizardData data) {
		return true;
	}

	/* @Override */
	public bool canFinish(ProjectWizardData data) {
		return data.getRepositoryName() != null;
	}

	/* @Override */
	public bool isApplicable(ProjectWizardData data) {
		return data.isSharedProject();
	}
}
